  if (!issued.ok) throw new Error(`issueInvoice failed: ${issued.error}`);

  const summary = vatSummary([issued.value]);

  assert.ok(summary.length > 0);
  // Base: 2 * 9500 = 19000, then 10% discount = 19000 - 1900 = 17100
  const lineSubtotal = 2 * 9500;
  const expectedBase = lineSubtotal - Math.round(lineSubtotal * 10 / 100);
  assert.equal(summary[0].base, expectedBase);
});

