    issueDate: '2024-03-15',
    lines: [{ sku: 'BRAND-BOOK', qty: 5 }],
  });
  if (!result.ok) throw new Error(`createInvoice failed: ${result.error}`);

  const issued = issueInvoice(result.value, []);
  if (!issued.ok) throw new Error(`issueInvoice failed: ${issued.error}`);

  const fee = lateFee(issued.value, '2024-05-15');

  assert.ok(fee > 0);
  assert.ok(Number.isInteger(fee));
});

test('lateFee multiple partial payments', () => {
  const invoice = createIssuedInvoice('C-001', '2024-03-15');
  const totals = invoiceTotals(invoice);
  const third = Math.floor(totals.total / 3);

  const payment1 = recordPayment(invoice, { amount: third, date: '2024-03-16' });
  const payment2 = recordPayment(payment1.value, { amount: third, date: '2024-03-17' });

  const fee = lateFee(payment2.value, '2024-04-20');

  // Remaining balance is one third
  const remaining = totals.total - third - third;
  const expectedFee = Math.round(remaining * 21 * 0.0004); // 21 days overdue (from 2024-04-14 to 2024-05-05... wait let me recalculate)
  // Actually asOf is 2024-04-20, so 6 days overdue from 2024-04-14
  const correctExpectedFee = Math.round(remaining * 6 * 0.0004);
  assert.equal(fee, correctExpectedFee);
});
